enable_sequencer.va.content:
`include "constants.vams"
`include "disciplines.vams"

module enable_sequencer (
    input  electrical clk,
    input  electrical rst_n_core,
    output electrical en_ana,
    output electrical en_dig
);
    parameter real vhi = 0.9;
    parameter real vlo = 0.0;
    parameter real vth = 0.45;
    parameter real tr = 200e-12;

    integer stage;
    real en_ana_target;
    real en_dig_target;

    analog begin
        @(initial_step) begin
            stage = 0;
        end

        @(cross(V(clk) - vth, +1)) begin
            if (V(rst_n_core) <= vth) begin
                stage = 0;
            end else if (stage < 2) begin
                stage = stage + 1;
            end
        end

        @(cross(V(rst_n_core) - vth, -1)) begin
            stage = 0;
        end

        en_ana_target = (V(rst_n_core) > vth && stage >= 1) ? vhi : vlo;
        en_dig_target = (V(rst_n_core) > vth && stage >= 2) ? vhi : vlo;
        V(en_ana) <+ transition(en_ana_target, 0, tr);
        V(en_dig) <+ transition(en_dig_target, 0, tr);
    end
endmodule

por_detector.va.content:
`include "constants.vams"
`include "disciplines.vams"

module por_detector (
    input  electrical vdd_sense,
    input  electrical clk,
    input  electrical rst_n_ext,
    output electrical por_n
);
    parameter real vhi = 0.9;
    parameter real vlo = 0.0;
    parameter real vpor = 0.72;
    parameter real vth = 0.45;
    parameter real tr = 200e-12;

    integer good_count;
    integer por_state;
    real por_target;

    analog begin
        @(initial_step) begin
            good_count = 0;
            por_state = 0;
        end

        @(cross(V(clk) - vth, +1)) begin
            if ((V(vdd_sense) >= vpor) && (V(rst_n_ext) > vth)) begin
                if (good_count < 2) begin
                    good_count = good_count + 1;
                end
                if (good_count >= 2) begin
                    por_state = 1;
                end
            end else begin
                good_count = 0;
                por_state = 0;
            end
        end

        @(cross(V(vdd_sense) - vpor, -1) or cross(V(rst_n_ext) - vth, -1)) begin
            good_count = 0;
            por_state = 0;
        end

        por_target = ((V(vdd_sense) >= vpor) && (V(rst_n_ext) > vth) && (por_state != 0)) ? vhi : vlo;
        V(por_n) <+ transition(por_target, 0, tr);
    end
endmodule

ready_flag.va.content:
`include "constants.vams"
`include "disciplines.vams"

module ready_flag (
    input  electrical clk,
    input  electrical en_ana,
    input  electrical en_dig,
    output electrical ready
);
    parameter real vhi = 0.9;
    parameter real vlo = 0.0;
    parameter real vth = 0.45;
    parameter real tr = 200e-12;

    integer ready_state;
    real ready_target;

    analog begin
        @(initial_step) begin
            ready_state = 0;
        end

        @(cross(V(clk) - vth, +1)) begin
            if ((V(en_ana) > vth) && (V(en_dig) > vth)) begin
                ready_state = 1;
            end else begin
                ready_state = 0;
            end
        end

        @(cross(V(en_ana) - vth, -1) or cross(V(en_dig) - vth, -1)) begin
            ready_state = 0;
        end

        ready_target = ((V(en_ana) > vth) && (V(en_dig) > vth) && (ready_state != 0)) ? vhi : vlo;
        V(ready) <+ transition(ready_target, 0, tr);
    end
endmodule

reset_synchronizer.va.content:
`include "constants.vams"
`include "disciplines.vams"

module reset_synchronizer (
    input  electrical clk,
    input  electrical por_n,
    input  electrical enable_req,
    output electrical rst_n_core
);
    parameter real vhi = 0.9;
    parameter real vlo = 0.0;
    parameter real vth = 0.45;
    parameter real tr = 200e-12;

    integer rst_state;
    real rst_target;

    analog begin
        @(initial_step) begin
            rst_state = 0;
        end

        @(cross(V(clk) - vth, +1)) begin
            if (V(por_n) <= vth) begin
                rst_state = 0;
            end else if (V(enable_req) > vth) begin
                rst_state = 1;
            end
        end

        @(cross(V(por_n) - vth, -1)) begin
            rst_state = 0;
        end

        rst_target = (V(por_n) > vth && (rst_state != 0)) ? vhi : vlo;
        V(rst_n_core) <+ transition(rst_target, 0, tr);
    end
endmodule
